const b = $json.body || $json;
const p = b.payload?.payment?.entity || {};
const n = p.notes || {};
return [{ json: { event: b.event || '', payment_id: p.id || '', order_id: p.order_id || '', amount: (Number(p.amount) || 0) / 100,
  currency: p.currency || 'INR', method: p.method || '', email: String(p.email || n.email || '').toLowerCase().trim(),
  phone: String(p.contact || n.phone || '').replace(/\D/g, ''), name: n.name || n.full_name || n.donor_name || '',
  pan: String(n.pan || n.pan_number || '').toUpperCase().trim(), address: n.address || '', campaign: n.campaign || n.purpose || 'General Fund',
  donor_type: /company|corporate|csr/i.test(n.donor_type || '') ? 'Corporate' : 'Individual',
  created_at: p.created_at ? new Date(p.created_at * 1000).toISOString() : new Date().toISOString() } }];

const NGO = {
  name: 'Your Foundation', legal_name: 'Your Foundation (Registered Public Charitable Trust)',
  address: 'Address line, City, State – PIN', pan: 'AAATXXXXXX', email: 'user@example.com', phone: '+91 9XXXXXXXXX',
  website: 'https://yourfoundation.example.org',
  reg_80g: 'AAATXXXXXXF20214', reg_80g_valid: 'AY 2022-23 to AY 2026-27', reg_12a: 'AAATXXXXXXE20214',
  csr1: 'CSR000XXXXX', fcra: '',                          // leave FCRA blank if not registered
  signatory: 'Authorised Signatory', signatory_title: 'Treasurer',
  // impact unit for thank-you copy: ₹ per unit
  impact_units: [{ per: 1500, unit: "a child's school kit for a year" }, { per: 6000, unit: 'a month of nutrition for a family' }, { per: 25000, unit: 'a year of schooling for a girl' }]
};
const e = $('Parse Payment Event').first().json;
const api = $('Verify with Razorpay API').first().json;
const ledger = $('Read Donations Ledger').all().map(i => i.json).filter(r => r.payment_id);
const P = api.body || {};
let status = 'new', reason = '';
if (ledger.some(r => r.payment_id === e.payment_id)) { status = 'duplicate'; reason = 'receipt already issued'; }
else if (api.statusCode !== 200) { status = 'mismatch'; reason = `Razorpay API HTTP ${api.statusCode}`; }
else if (P.status !== 'captured' || Number(P.amount) / 100 !== e.amount) { status = 'mismatch'; reason = `API status ${P.status}, amount ₹${Number(P.amount) / 100} vs webhook ₹${e.amount}`; }

// Financial year + sequential receipt number
const d = DateTime.fromISO(e.created_at).setZone('Asia/Kolkata');
const fyStart = d.month >= 4 ? d.year : d.year - 1;
const fy = `${fyStart}-${String((fyStart + 1) % 100).padStart(2, '0')}`;
const seq = ledger.filter(r => r.fy === fy).length + 1;
const receipt_no = `80G/${fy}/${String(seq).padStart(6, '0')}`;

// Donor history & tier
const key = r => (r.email || '').toLowerCase() || String(r.phone || '');
const mine = ledger.filter(r => key(r) && key(r) === (e.email || e.phone));
const prevTotal = mine.reduce((a, r) => a + (Number(r.amount) || 0), 0);
const lifetime = prevTotal + e.amount;
const tierOf = t => t >= 100000 ? 'Patron' : t >= 25000 ? 'Champion' : t >= 5000 ? 'Supporter' : 'Friend';
const last12 = mine.filter(r => DateTime.fromISO(String(r.donated_at)) > d.minus({ months: 12 })).length + 1;

// Amount in words (Indian system)
const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
const two = n => n < 20 ? ones[n] : tens[Math.floor(n / 10)] + (n % 10 ? ' ' + ones[n % 10] : '');
const three = n => n >= 100 ? ones[Math.floor(n / 100)] + ' Hundred' + (n % 100 ? ' ' + two(n % 100) : '') : two(n);
const words = num => { num = Math.floor(num); if (!num) return 'Zero'; let s = '';
  const cr = Math.floor(num / 1e7); num %= 1e7; const lk = Math.floor(num / 1e5); num %= 1e5; const th = Math.floor(num / 1000); num %= 1000;
  if (cr) s += words(cr) + ' Crore '; if (lk) s += two(lk) + ' Lakh '; if (th) s += two(th) + ' Thousand '; if (num) s += three(num);
  return s.trim(); };
const paise = Math.round((e.amount % 1) * 100);
const impact = [...NGO.impact_units].reverse().find(u => e.amount >= u.per) || NGO.impact_units[0];

return [{ json: { ...e, status, reason, ngo: NGO, fy, receipt_no, receipt_date: d.toFormat('dd LLL yyyy'),
  name: e.name || P.notes?.name || 'Donor', email: e.email || P.email || '', method: P.method || e.method,
  amount_words: `Rupees ${words(e.amount)}${paise ? ' and ' + two(paise) + ' Paise' : ''} Only`,
  pan_valid: /^[A-Z]{5}[0-9]{4}[A-Z]$/.test(e.pan),
  donation_count: mine.length + 1, previous_total: prevTotal, lifetime_total: lifetime,
  previous_tier: mine.length ? tierOf(prevTotal) : 'New', tier: tierOf(lifetime), tier_upgraded: mine.length > 0 && tierOf(prevTotal) !== tierOf(lifetime),
  recurring: last12 >= 3, major_gift: e.amount >= 50000, first_gift: mine.length === 0,
  impact_units: Math.max(1, Math.floor(e.amount / impact.per)), impact_unit: impact.unit } }];

