const end = $now.setZone('Asia/Kolkata').startOf('month');
const start = end.minus({ months: 3 });
const fyQ = (() => { const m = start.month; const q = m >= 4 && m <= 6 ? 1 : m >= 7 && m <= 9 ? 2 : m >= 10 ? 3 : 4;
  const fyStart = m >= 4 ? start.year : start.year - 1; return `Q${q} FY${fyStart}-${String((fyStart + 1) % 100).padStart(2, '0')}`; })();
return [{ json: { start: start.toISO(), end: end.toISO(), label: fyQ, period: `${start.toFormat('LLL')}–${end.minus({ days: 1 }).toFormat('LLL yyyy')}`,
  comms_email: 'REPLACE_WITH_COMMS_EMAIL', ngo_name: 'Your Foundation' } }];

const w = $('Set Quarter Window').first().json;
const inQ = r => r.donated_at && r.donated_at >= w.start && r.donated_at < w.end;
const all = $('Read Donations (Quarter)').all().map(i => i.json).filter(r => r.payment_id);
const q = all.filter(inQ);
const sum = a => a.reduce((t, r) => t + (Number(r.amount) || 0), 0);
const by = (a, k) => Object.entries(a.reduce((m, r) => { m[r[k] || 'Other'] = (m[r[k] || 'Other'] || 0) + (Number(r.amount) || 0); return m; }, {})).sort((x, y) => y[1] - x[1]);
const donors = {}; q.forEach(r => { const k = r.email || r.phone; if (k) (donors[k] = donors[k] || { name: r.name, email: r.email, tier: r.tier }); });
const seenBefore = new Set(all.filter(r => r.donated_at < w.start).map(r => r.email || r.phone));
const tiers = {}; Object.values(donors).forEach(d => { (tiers[d.tier || 'Friend'] = tiers[d.tier || 'Friend'] || []).push(d); });
// every donor ever, by current tier, for the update
const latest = {}; all.forEach(r => { const k = r.email; if (k && (!latest[k] || r.donated_at > latest[k].donated_at)) latest[k] = r; });
const audience = {}; Object.values(latest).forEach(r => (audience[r.tier || 'Friend'] = audience[r.tier || 'Friend'] || []).push(r.email));
const metrics = $('Read Impact Metrics').all().map(i => i.json).filter(m => m.program && (!m.quarter || String(m.quarter).includes(w.label.split(' ')[0])));
return [{ json: { ...w, raised: sum(q), gifts: q.length, donors: Object.keys(donors).length,
  new_donors: Object.keys(donors).filter(k => !seenBefore.has(k)).length, recurring: q.filter(r => String(r.recurring) === 'true').length,
  by_campaign: by(q, 'campaign').slice(0, 6), by_tier: by(q, 'tier'), metrics: metrics.slice(0, 20),
  audience, audience_counts: Object.fromEntries(Object.entries(audience).map(([k, v]) => [k, v.length])) } }];

const a = $('Aggregate Quarter').first().json;
const ai = $input.first().json.message?.content || {};
const order = ['Patron', 'Champion', 'Supporter', 'Friend'];
return order.filter(t => (a.audience[t] || []).length).map(t => {
  const personal = ['Patron', 'Champion'].includes(t) ? ai.patron_note_html : ai.friend_note_html;
  const list = a.audience[t];
  return { json: { tier: t, count: list.length, to: a.comms_email, bcc: list.slice(0, 450).join(','), overflow: Math.max(0, list.length - 450),
    subject: `${ai.subject || a.label + ' impact update'}`,
    html: `<p style="color:#888;font-size:12px">[DRAFT · ${t} segment · ${list.length} donors in BCC${list.length > 450 ? ` · ${list.length - 450} more need a second send` : ''}]</p>` +
      `<h2>${ai.headline || ''}</h2>${t === 'Patron' ? '<p>Dear friend,</p>' : '<p>Hello!</p>'}${ai.body_html || ''}${personal || ''}<p>With gratitude,<br>${a.ngo_name}</p>` } };
});

const NGO = {
  name: 'Your Foundation', legal_name: 'Your Foundation (Registered Public Charitable Trust)',
  address: 'Address line, City, State – PIN', pan: 'AAATXXXXXX', email: 'user@example.com', phone: '+91 9XXXXXXXXX',
  website: 'https://yourfoundation.example.org',
  reg_80g: 'AAATXXXXXXF20214', reg_80g_valid: 'AY 2022-23 to AY 2026-27', reg_12a: 'AAATXXXXXXE20214',
  csr1: 'CSR000XXXXX', fcra: '',                          // leave FCRA blank if not registered
  signatory: 'Authorised Signatory', signatory_title: 'Treasurer',
  // impact unit for thank-you copy: ₹ per unit
  impact_units: [{ per: 1500, unit: "a child's school kit for a year" }, { per: 6000, unit: 'a month of nutrition for a family' }, { per: 25000, unit: 'a year of schooling for a girl' }]
};
const f = $('CSR Enquiry Form').first().json;
const budgetMid = { 'Under 10 Lakh': 700000, '10–50 Lakh': 3000000, '50 Lakh – 2 Crore': 12500000, 'Above 2 Crore': 30000000 }[f['CSR Budget (INR)']] || 3000000;
const focus = String(f['Focus Areas (Schedule VII)'] || '').toLowerCase().split(/[,;/]| and /).map(s => s.trim()).filter(Boolean);
const geo = String(f['Preferred Geography'] || '').toLowerCase();
const progs = $input.all().map(i => i.json).filter(p => p.program).map(p => {
  const tags = `${p.focus_areas || ''} ${p.schedule_vii || ''} ${p.program}`.toLowerCase();
  const fScore = focus.filter(x => x && tags.includes(x.split(' ')[0])).length;
  const states = String(p.states || '').toLowerCase();
  const gScore = !geo ? 0.5 : states.split(/[,;]/).some(s => s.trim() && geo.includes(s.trim())) ? 1 : states.includes('pan-india') ? 0.6 : 0;
  const minB = Number(p.min_budget) || 0;
  const bScore = budgetMid >= minB ? 1 : budgetMid >= minB * 0.6 ? 0.5 : 0;
  const cpb = Number(p.cost_per_beneficiary) || 0;
  return { ...p, match: Math.round((fScore * 3 + gScore * 2 + bScore * 2) * 10) / 10, est_beneficiaries: cpb ? Math.floor(budgetMid * 0.9 / cpb) : null };
}).sort((a, b) => b.match - a.match);
const picked = progs.filter(p => p.match >= 2).slice(0, 3);
const id = `CSR-${$now.toFormat('yyMMdd')}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
return [{ json: { lead_id: id, ngo: NGO, company: f['Company Name'], contact: f['Contact Person'], designation: f['Designation'] || '',
  email: f['Email'], phone: f['Phone'] || '', budget_band: f['CSR Budget (INR)'], budget_mid: budgetMid, focus_areas: f['Focus Areas (Schedule VII)'],
  geography: f['Preferred Geography'] || 'Flexible', timeline: f['Timeline / FY'] || '', notes: f['Anything else we should know?'] || '',
  matched_programs: (picked.length ? picked : progs.slice(0, 2)).map(p => ({ program: p.program, schedule_vii: p.schedule_vii, states: p.states,
    cost_per_beneficiary: p.cost_per_beneficiary, outcomes: p.outcomes, est_beneficiaries: p.est_beneficiaries, match: p.match })),
  fit: picked.length ? (picked[0].match >= 5 ? 'Strong' : 'Good') : 'Partial' } }];

const L = $('Match Programs to CSR Brief').first().json, N = L.ngo;
const a = $input.first().json.message?.content || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const inr = v => '₹' + Number(v || 0).toLocaleString('en-IN');
const total = (a.budget_table || []).reduce((t, r) => t + (Number(r.amount_inr) || 0), 0);
const html = `<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#1d2733;font-size:12px;line-height:1.5}
.cover{background:#17344d;color:#fff;padding:28px;border-radius:10px}.cover h1{margin:0 0 8px;font-size:24px}h2{color:#17344d;border-bottom:2px solid #e67e22;padding-bottom:3px;font-size:15px;margin-top:20px}
table{width:100%;border-collapse:collapse}td,th{border:1px solid #ddd;padding:6px 8px;text-align:left}th{background:#f3f6f9}.c{font-size:10px;color:#667}</style></head><body>
<div class="cover"><h1>${esc(a.title || 'CSR Partnership Proposal')}</h1>Prepared for <b>${esc(L.company)}</b> · Attn: ${esc(L.contact)} ${L.designation ? '(' + esc(L.designation) + ')' : ''}<br>
By ${esc(N.legal_name)} · Ref ${L.lead_id} · ${$now.toFormat('dd LLL yyyy')}</div>
<h2>Executive summary</h2><p>${esc(a.executive_summary)}</p><h2>Alignment with Schedule VII & your CSR policy</h2><p>${esc(a.alignment)}</p>
<h2>Proposed programmes</h2>${(a.programs || []).map(p => `<p><b>${esc(p.name)}</b><br>${esc(p.what)}<br><i>Where:</i> ${esc(p.where)} · <i>Beneficiaries:</i> ${esc(p.beneficiaries)}<br><i>Outcomes:</i> ${esc(p.outcomes)}</p>`).join('')}
<h2>Budget</h2><table><tr><th>Head</th><th>Amount</th></tr>${(a.budget_table || []).map(r => `<tr><td>${esc(r.head)}</td><td>${inr(r.amount_inr)}</td></tr>`).join('')}<tr><th>Total</th><th>${inr(total)}</th></tr></table>
<h2>KPIs</h2><ul>${(a.kpis || []).map(k => `<li>${esc(k)}</li>`).join('')}</ul><h2>Monitoring & evaluation</h2><p>${esc(a.me_framework)}</p>
<h2>Timeline</h2><table><tr><th>Phase</th><th>Months</th></tr>${(a.timeline || []).map(t => `<tr><td>${esc(t.phase)}</td><td>${esc(t.months)}</td></tr>`).join('')}</table>
<h2>Reporting</h2><p>${esc(a.reporting)}</p><h2>Why ${esc(N.name)}</h2><p>${esc(a.why_us)}</p>
<h2>Compliance</h2><table><tr><td>CSR-1 Registration</td><td>${N.csr1 || '–'}</td></tr><tr><td>12A</td><td>${N.reg_12a}</td></tr><tr><td>80G</td><td>${N.reg_80g}</td></tr><tr><td>PAN</td><td>${N.pan}</td></tr>${N.fcra ? `<tr><td>FCRA</td><td>${N.fcra}</td></tr>` : ''}</table>
<h2>Next steps</h2><p>${esc(a.next_steps)}</p><p class="c">${esc(N.name)} · ${N.email} · ${N.phone} · ${N.website}</p></body></html>`;
return [{ json: { html, total, file_name: `CSR_Proposal_${L.company.replace(/[^A-Za-z0-9]+/g, '_')}_${L.lead_id}.pdf`, cover_email: a.cover_email || '' } }];

